(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-3-inner-ear-hearing-loss-vignettes-version-2"]={"title":"Inner Ear and Hearing Loss Vignettes 2 — CMS I Exam 3","category":"Clinical Medicine and Surgery I","exam":"Exam 3","sem":"fall-2026","questions":[{"q":"A 42-year-old man with sudden vertigo and hearing loss develops a fever of thirty-nine degrees Celsius. How does this change management?","choices":["Arrange a hearing aid","Reassure and discharge","Add antibiotics","Stop all treatment","Perform the Epley manoeuvre"],"answer":2,"exp":"Correct — antibiotics are given if bacterial features are present. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 95"},{"q":"A 50-year-old woman with episodic vertigo has an audiogram showing loss confined to the low frequencies, which improves between attacks. What does this pattern suggest?","choices":["Otosclerosis","Acoustic neuroma","Meniere disease","Presbycusis","Noise-induced loss"],"answer":2,"exp":"Correct — low-frequency, fluctuating sensorineural loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 69"},{"q":"A 58-year-old woman is starting a prolonged aminoglycoside course. Which monitoring is required?","choices":["No monitoring is needed","Peak drug levels","Weekly tympanometry","Daily otoscopy","Monthly imaging"],"answer":1,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 52"},{"q":"A 40-year-old woman with a normal-looking drum and conductive hearing loss has a tympanogram with normal pressure but unusually low compliance. What does this suggest?","choices":["A normal middle ear","Ossicular fixation","Ossicular discontinuity","Middle ear fluid","Negative middle ear pressure"],"answer":1,"exp":"Correct — a shallow type As trace, fitting otosclerosis. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 28"},{"q":"A 66-year-old man attends for a routine visit with no hearing complaint. What is appropriate?","choices":["Immediate referral for a hearing aid","An urgent magnetic resonance scan","Tympanometry only","Screen his hearing","No action unless he complains"],"answer":3,"exp":"Correct — screening is routine from age sixty-five. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 60"},{"q":"A 44-year-old woman has a three-year history of gradual hearing loss in the left ear with a normal-looking drum, and says she hears better in noisy rooms. Which tuning fork findings are expected?","choices":["Weber to the left; left air conduction greater than bone","Weber to the left; left bone conduction at least equal to air","Weber to the right; left air conduction greater than bone","Weber to the right; left bone conduction greater than air","No lateralisation at all"],"answer":1,"exp":"Correct. Otosclerosis is a conductive loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 42"},{"q":"A 60-year-old man has a small acoustic neuroma with mild symptoms. Which options should be discussed?","choices":["Tympanostomy tubes","No treatment is ever available","Observation with annual imaging, surgery or radiation","Antibiotics alone","Ear drops alone"],"answer":2,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 75"},{"q":"A 20-year-old man leaves a concert with muffled hearing, a sensation of fullness and a chirping noise. By the next afternoon his hearing is back to normal. What has happened?","choices":["A permanent threshold shift","Acoustic trauma with perforation","Sudden sensorineural hearing loss","Barotrauma","A temporary threshold shift"],"answer":4,"exp":"Correct — but repeated exposures make the loss permanent. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 54"},{"q":"A 45-year-old woman has recurrent attacks of spinning that last three to four hours, with nausea, a low roaring noise and a feeling of pressure in the right ear. Her hearing fluctuates. Which feature separates this from positional vertigo?","choices":["Hearing is affected","Nausea is present","The onset is sudden","It recurs","It is one-sided"],"answer":0,"exp":"Correct — positional vertigo leaves hearing untouched and causes no tinnitus. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 69"},{"q":"A 44-year-old man in the acute phase of vestibular neuronitis is vomiting repeatedly. Which combination is appropriate?","choices":["Antibiotics and an antiemetic","An antifungal and rest","A diuretic and salt restriction","Immediate surgery","Meclizine and an antiemetic"],"answer":4,"exp":"Correct; the role of oral corticosteroids is uncertain. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 96"},{"q":"A 47-year-old woman describes ringing in the right ear only, which she can hear beating in time with her pulse. What is the appropriate response?","choices":["Reassure her that this is normal head noise","Prescribe an antihistamine","Advise her to avoid quiet rooms","Arrange review in one year","Investigate further"],"answer":4,"exp":"Correct — unilateral and pulsatile tinnitus are both red flags. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 45"},{"q":"A 64-year-old man treated with intravenous gentamicin for two weeks develops hearing loss in both ears. His canals and drums are normal. What is the most likely cause?","choices":["Acoustic neuroma","Ototoxicity","Presbycusis","Otosclerosis","Cerumen impaction"],"answer":1,"exp":"Correct — aminoglycosides are the most ototoxic and the most commonly implicated. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 52"},{"q":"A 35-year-old man develops sudden hearing loss and vertigo immediately after lifting a heavy weight, hearing a pop at the moment of onset. What is the likely mechanism?","choices":["Fixation of the stapes","An abnormal opening at the round or oval window","Inflammation of the vestibular nerve","Debris in the semicircular canal","A tumour of the eighth nerve"],"answer":1,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 63"},{"q":"A 43-year-old woman has bilateral hearing loss that has worsened in steps over two years, with periods of stability between. What does this pattern suggest?","choices":["Noise-induced loss","Cerumen impaction","Otosclerosis","An autoimmune cause","Presbycusis"],"answer":3,"exp":"Correct — deterioration alternating with stabilisation is characteristic. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 65"},{"q":"A 78-year-old man says he can hear people speaking but cannot make out the words, and he misses the doorbell. Both ears are affected equally and his canals and drums are normal. What is the most likely diagnosis?","choices":["Presbycusis","Otosclerosis","Cerumen impaction","Acoustic neuroma","Meniere disease"],"answer":0,"exp":"Correct — bilateral, symmetrical, gradual high-frequency loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 60"},{"q":"A 70-year-old woman with vertigo also has a new headache and cannot walk in a straight line. What should be done?","choices":["Prescribe meclizine and review in a month","Arrange a hearing aid","Reassure and discharge","Refer urgently for neuroimaging","Treat as positional vertigo"],"answer":3,"exp":"Correct — ataxia and headache with vertigo are warning features. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 78"},{"q":"A 36-year-old man has dramatic sudden vertigo with nausea and unsteadiness. His hearing is normal and there are no focal neurological findings. What should he be told about the outlook?","choices":["It indicates a brain tumour","It will recur every week indefinitely","It is benign and self-limiting","It will progress to permanent deafness","It requires urgent surgery"],"answer":2,"exp":"Correct, though balance symptoms may last months. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 96"},{"q":"A 34-year-old man standing beside an explosion has immediate hearing loss and a perforated drum. What describes this injury?","choices":["Presbycusis","Ototoxicity","Acoustic trauma","Noise-induced hearing loss","Barotrauma"],"answer":2,"exp":"Correct — a single loud noise causing immediate loss. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 56"},{"q":"A 5-year-old boy has reduced hearing. His tympanogram is a flat line with no pressure peak. Which finding does this indicate?","choices":["Ossicular discontinuity","Fluid in the middle ear","A normal middle ear","Negative middle ear pressure","A fixed stapes"],"answer":1,"exp":"Correct — a type B trace. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 26"},{"q":"A 39-year-old man reports right ear fullness and reduced hearing that began after a head cold. He denies ringing, dizziness, fever and discharge. An amber effusion is visible behind an intact right drum, which moves poorly. The left ear is normal. Which tuning fork findings are most likely?","choices":["Weber to the left; right bone conduction greater than air","No lateralisation; air conduction greater than bone bilaterally","Weber to the right; right bone conduction at least equal to air","Weber to the left; right air conduction greater than bone","Weber to the right; right air conduction greater than bone"],"answer":2,"exp":"Correct. A right middle ear effusion is a conductive loss, so Weber lateralises to it and Rinne becomes abnormal there. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 42"},{"q":"A 76-year-old man has acute vertigo with facial weakness, loss of pain sensation on one side of his face and the opposite side of his body, and a drooping eyelid. What does this require?","choices":["The Epley manoeuvre","Reassurance and meclizine","Routine audiometry","Antibiotic ear drops","Emergency evaluation for stroke"],"answer":4,"exp":"Correct — crossed sensory findings mean a brainstem problem. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 77"},{"q":"A 30-year-old woman with a blocked ear speaks unusually softly during the consultation. What does this suggest about her hearing loss?","choices":["It is sensorineural","It is functional","It is profound and bilateral","It is central in origin","It is conductive"],"answer":4,"exp":"Correct — she hears her own voice well because the inner ear is intact. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 42"},{"q":"A 55-year-old woman reports positional spinning attacks that each last twenty minutes. What should this prompt?","choices":["Reassurance that this is typical","Starting a diuretic","Referral for a hearing aid","Considering an alternative diagnosis","Immediate Epley treatment"],"answer":3,"exp":"Correct — beyond a minute, positional vertigo becomes unlikely. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 91"},{"q":"A 40-year-old diver has sudden hearing loss and vertigo after a dive, with a popping sensation at onset. What is appropriate management?","choices":["Reassurance alone","The Epley manoeuvre","Antibiotic drops","Immediate wax removal","Symptomatic treatment and specialist referral"],"answer":4,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 64"},{"q":"A 62-year-old man treated for positional vertigo asks why he still feels unsteady hours later. What should he be told?","choices":["This indicates a stroke","This means the diagnosis was wrong","This is a side effect of the manoeuvre","Imbalance can persist for hours after an episode","This means the treatment failed"],"answer":3,"exp":"Correct, and chronic balance complaints are common. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 92"},{"q":"A 9-year-old boy has sensorineural hearing loss and blood in his urine. Which hereditary condition should be considered?","choices":["Alport syndrome","Usher syndrome","Waardenburg syndrome","Meniere disease","Otosclerosis"],"answer":0,"exp":"Correct — hearing loss with kidney involvement. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 71"},{"q":"A 62-year-old woman on furosemide, aspirin and platinum-based chemotherapy develops bilateral hearing loss. What should be considered?","choices":["All three agents are ototoxic","Only the aspirin is relevant","Only the furosemide is relevant","None of these affects hearing","Only the chemotherapy is relevant"],"answer":0,"exp":"Correct — each is named as such. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 52"},{"q":"A 60-year-old woman is referred for formal hearing assessment. Single tones are presented at set frequencies and she signals the softest she can hear. Which test is this?","choices":["Pure tone audiometry","Tympanometry","Electronystagmography","The Dix-Hallpike manoeuvre","The Rinne test"],"answer":0,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 8"},{"q":"A 51-year-old woman with sudden one-sided hearing loss asks why she must be seen the same day. What should she be told?","choices":["Surgery must be done within hours","It always signals a tumour","The other ear will be affected by tomorrow","Treatment works only if started early","The condition is contagious"],"answer":3,"exp":"Correct. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 79"},{"q":"A 58-year-old woman has brief spinning attacks whenever she rolls over in bed, each lasting under a minute, with normal hearing. Which test should be performed?","choices":["The Dix-Hallpike manoeuvre","The Epley manoeuvre","Tympanometry","The Weber test","Magnetic resonance angiography"],"answer":0,"exp":"Correct — it provokes the classic eye movements. — 16. Disorders of Inner Ear 2026 - Dr. Jaquith.pptx, Slide 93"}]};
